{
  "states": [
    "initial state",
    "mail transaction in progress"
  ],
  "transitions": [
    {
      "from": "initial state",
      "event": "MAIL",
      "action": "clears the reverse-path buffer, the forward-path buffer, and the mail data buffer, and it inserts the reverse-path information from its argument clause into the reverse-path buffer",
      "to": "mail transaction in progress"
    },
    {
      "from": "mail transaction in progress",
      "event": "RCPT",
      "action": "appends its forward-path argument to the forward-path buffer",
      "to": "mail transaction in progress"
    },
    {
      "from": "mail transaction in progress",
      "event": "end of mail data indication",
      "action": "process the stored mail transaction information, consumes the information in the reverse-path buffer, the forward-path buffer, and the mail data buffer, and on the completion of this command these buffers are cleared; send an OK reply or failure reply",
      "to": "initial state"
    },
    {
      "from": "mail transaction in progress",
      "event": "RSET",
      "action": "stored sender, recipients, and mail data MUST be discarded, and all buffers and state tables cleared; send a '250 OK' reply",
      "to": "initial state"
    },
    {
      "from": "initial state",
      "event": "RSET",
      "action": "stored sender, recipients, and mail data MUST be discarded, and all buffers and state tables cleared; send a '250 OK' reply",
      "to": "initial state"
    }
  ]
}

